SELECT gen_random_uuid()::text, 'formula', '$\mathbf{E} = \mathbf{V} + \mathbf{I}(R_a + jX_s)$', 'Generated EMF by Phasors', '$\mathbf{E} = \mathbf{V} + \mathbf{I}(R_a + jX_s)\quad (\text{generator, per phase})$', '$\text{V}$', 'The excitation EMF an alternator needs to hold V at a given load: the synchronous-impedance method.', '[{"symbol":"$V$","meaning":"terminal voltage per phase","unit":"$\\text{V}$"},{"symbol":"$\\mathbf{I}$","meaning":"armature current at the load angle","unit":"$\\text{A}$"},{"symbol":"$R_a, X_s$","meaning":"armature resistance and synchronous reactance","unit":"$\\Omega$"}]'::jsonb, 'Lagging load: E much larger than V. Leading load can make E LESS than V, so regulation goes negative.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'voltage regulation' AND s."active"), NULL, false, 'PENDING', now(), now()
