SELECT gen_random_uuid()::text, 'formula', '$P = \frac{3EV}{X_s}\sin\delta$', 'Power-Angle Equation', '$P = \frac{3EV}{X_s}\sin\delta,\qquad Q = \frac{3V(E\cos\delta - V)}{X_s}\quad (\text{per-phase } E, V)$', '$\text{W}$', 'The real and reactive power of a round-rotor machine on a bus, with R_a neglected.', '[{"symbol":"$E$","meaning":"generated (excitation) EMF per phase","unit":"$\\text{V}$"},{"symbol":"$V$","meaning":"terminal voltage per phase","unit":"$\\text{V}$"},{"symbol":"$X_s$","meaning":"synchronous reactance per phase","unit":"$\\Omega$"},{"symbol":"$\\delta$","meaning":"power (load) angle between E and V","unit":null}]'::jsonb, 'Maximum (steady-state limit) at δ = 90°. Overexcited (E cos δ > V) the machine supplies vars.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'parallel operation of alternators' AND s."active"), NULL, false, 'PENDING', now(), now()
