SELECT gen_random_uuid()::text, 'formula', '$P = \frac{EV}{X_d}\sin\delta + (\dots)\sin2\delta$', 'Salient-Pole Power-Angle Equation', '$P =\frac{EV}{X_d}\sin\delta + \frac{V^2}{2}\left(\frac{1}{X_q} - \frac{1}{X_d}\right)\sin2\delta\quad (\text{per phase})$', '$\text{W}$', 'A salient-pole machine adds reluctance power, which exists even with no field.', '[{"symbol":"$E$","meaning":"generated (excitation) EMF per phase","unit":"$\\text{V}$"},{"symbol":"$V$","meaning":"terminal voltage per phase","unit":"$\\text{V}$"},{"symbol":"$X_d, X_q$","meaning":"direct- and quadrature-axis reactances","unit":"$\\Omega$"},{"symbol":"$\\delta$","meaning":"power (load) angle between E and V","unit":null}]'::jsonb, 'Its maximum comes before δ = 90°.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'parallel operation of alternators' AND s."active"), NULL, false, 'PENDING', now(), now()
