SELECT gen_random_uuid()::text, 'formula', '$I_c = \frac{E_1 - E_2}{Z_1 + Z_2}$', 'Synchronizing Current Between Alternators', '$\mathbf{I}_c = \frac{\mathbf{E}_1 - \mathbf{E}_2}{Z_{s1} + Z_{s2}}$', '$\text{A}$', 'The current that circulates between paralleled alternators whose EMFs differ in size or phase.', '[{"symbol":"$\\mathbf{E}_1, \\mathbf{E}_2$","meaning":"the two EMFs (phasors)","unit":"$\\text{V}$"},{"symbol":"$Z_{s1}, Z_{s2}$","meaning":"their synchronous impedances","unit":"$\\Omega$"}]'::jsonb, 'A phase difference makes real synchronizing power; a size difference only circulates vars.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'parallel operation of alternators' AND s."active"), NULL, false, 'PENDING', now(), now()
