SELECT gen_random_uuid()::text, 'formula', '$\mathbf{E} = \mathbf{V} - \mathbf{I}(R_a + jX_s)$', 'Synchronous Motor EMF', '$\mathbf{E} = \mathbf{V} - \mathbf{I}(R_a + jX_s)\quad (\text{motor, per phase})$', '$\text{V}$', 'The back EMF of a synchronous motor: the motor form of the alternator equation.', '[{"symbol":"$V$","meaning":"terminal voltage per phase","unit":"$\\text{V}$"},{"symbol":"$\\mathbf{I}$","meaning":"armature current drawn","unit":"$\\text{A}$"},{"symbol":"$R_a, X_s$","meaning":"armature resistance and synchronous reactance","unit":"$\\Omega$"}]'::jsonb, 'E lags V by the load angle δ; more load, larger δ, same speed.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'synchronous motors and v-curves' AND s."active"), NULL, false, 'PENDING', now(), now()
