SELECT gen_random_uuid()::text, 'formula', '$P_{\max} = \frac{3EV}{X_s}$', 'Pull-Out Power and Torque', '$P_{\max} = \frac{3EV}{X_s},\qquad T_{\max} = \frac{P_{\max}}{\omega_s}$', '$\text{W}$', 'The largest load a synchronous motor can carry before it falls out of step.', '[{"symbol":"$E$","meaning":"generated (excitation) EMF per phase","unit":"$\\text{V}$"},{"symbol":"$V$","meaning":"terminal voltage per phase","unit":"$\\text{V}$"},{"symbol":"$X_s$","meaning":"synchronous reactance per phase","unit":"$\\Omega$"},{"symbol":"$\\omega_s$","meaning":"synchronous speed, 2πN_s/60","unit":"$\\text{rad/s}$"}]'::jsonb, 'More field current (larger E) raises the pull-out torque.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'synchronous motors and v-curves' AND s."active"), NULL, false, 'PENDING', now(), now()
