SELECT gen_random_uuid()::text, 'formula', '$E = \sqrt{V^2 + (IX_s)^2}$', 'Excitation for Unity Power Factor', '$I = \frac{P}{3V},\qquad E = \sqrt{V^2 + (IX_s)^2}\quad (R_a \text{ neglected})$', '$\text{V}$', 'The EMF at the bottom of a V-curve, where the armature current is least.', '[{"symbol":"$P$","meaning":"motor input power","unit":"$\\text{W}$"},{"symbol":"$V$","meaning":"terminal voltage per phase","unit":"$\\text{V}$"},{"symbol":"$X_s$","meaning":"synchronous reactance per phase","unit":"$\\Omega$"}]'::jsonb, 'Less excitation: lagging and more current. More: leading and more current. Hence the V.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'synchronous motors and v-curves' AND s."active"), NULL, false, 'PENDING', now(), now()
