SELECT gen_random_uuid()::text, 'formula', '$T = \frac{3V^2R_2/s}{\omega_s[(R_1 + R_2/s)^2 + X^2]}$', 'Torque-Slip Equation', '$T = \frac{3V^2(R_2/s)}{\omega_s\left[(R_1 + R_2/s)^2 + (X_1 + X_2)^2\right]}$', '$\text{N·m}$', 'Induction motor torque at any slip, from the approximate equivalent circuit.', '[{"symbol":"$V$","meaning":"terminal voltage per phase","unit":"$\\text{V}$"},{"symbol":"$R_1$","meaning":"stator resistance","unit":"$\\Omega$"},{"symbol":"$R_2$","meaning":"rotor resistance referred to the stator","unit":"$\\Omega$"},{"symbol":"$X_1 + X_2$","meaning":"stator plus referred rotor reactance","unit":"$\\Omega$"},{"symbol":"$s$","meaning":"slip, as a decimal","unit":null},{"symbol":"$\\omega_s$","meaning":"synchronous speed, 2πN_s/60","unit":"$\\text{rad/s}$"}]'::jsonb, 'Near synchronous speed T is about proportional to s; near standstill about 1/s.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'induction motor slip and torque' AND s."active"), NULL, false, 'PENDING', now(), now()
