SELECT gen_random_uuid()::text, 'formula', '$s_{mT} = \frac{R_2}{\sqrt{R_1^2 + (X_1 + X_2)^2}}$', 'Slip at Maximum Torque', '$s_{mT} = \frac{R_2}{\sqrt{R_1^2 + (X_1 + X_2)^2}} \approx \frac{R_2}{X_2}$', NULL, 'The slip where torque peaks: proportional to rotor resistance.', '[{"symbol":"$R_2$","meaning":"rotor resistance referred to the stator","unit":"$\\Omega$"},{"symbol":"$R_1$","meaning":"stator resistance","unit":"$\\Omega$"},{"symbol":"$X_1 + X_2$","meaning":"stator plus referred rotor reactance","unit":"$\\Omega$"}]'::jsonb, 'Adding rotor resistance moves the peak to higher slip without changing its height.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'induction motor slip and torque' AND s."active"), NULL, true, 'PENDING', now(), now()
