SELECT gen_random_uuid()::text, 'formula', '$T_{\max} \propto \frac{V^2}{R_1 + \sqrt{R_1^2 + X^2}}$', 'Maximum (Breakdown) Torque', '$T_{\max} = \frac{3V^2}{2\omega_s\left[R_1 + \sqrt{R_1^2 + (X_1 + X_2)^2}\right]}$', '$\text{N·m}$', 'The pull-out torque of an induction motor.', '[{"symbol":"$V$","meaning":"terminal voltage per phase","unit":"$\\text{V}$"},{"symbol":"$R_1$","meaning":"stator resistance","unit":"$\\Omega$"},{"symbol":"$X_1 + X_2$","meaning":"stator plus referred rotor reactance","unit":"$\\Omega$"},{"symbol":"$\\omega_s$","meaning":"synchronous speed, 2πN_s/60","unit":"$\\text{rad/s}$"}]'::jsonb, 'It does NOT depend on R₂, and varies with V²: a 10% voltage dip costs 19% of it.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'induction motor slip and torque' AND s."active"), NULL, false, 'PENDING', now(), now()
