SELECT gen_random_uuid()::text, 'formula', '$\frac{T}{T_{\max}} = \frac{2}{s/s_m + s_m/s}$', 'Torque Ratio to Maximum (Kloss)', '$\frac{T}{T_{\max}} = \frac{2}{s/s_m + s_m/s};\qquad \frac{T_{st}}{T_{\max}} = \frac{2s_m}{1 + s_m^2}\quad (R_1 \text{ neglected})$', NULL, 'Torque at any slip as a fraction of breakdown torque, from the slip of maximum torque.', '[{"symbol":"$s$","meaning":"slip, as a decimal","unit":null},{"symbol":"$s_m$","meaning":"slip at maximum torque","unit":null}]'::jsonb, 'Put s = 1 for the starting torque ratio.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'induction motor slip and torque' AND s."active"), NULL, true, 'PENDING', now(), now()
