SELECT gen_random_uuid()::text, 'formula', '$P_g : P_{rcl} : P_m = 1 : s : (1 - s)$', 'Induction Motor Power Flow', '$P_{in} = P_{scl} + P_{core} + P_g,\qquad P_g : P_{rcl} : P_m = 1 : s : (1 - s),\qquad P_{out} = P_m - P_{f\&w}$', NULL, 'Where an induction motor''s input power goes, from the supply to the shaft.', '[{"symbol":"$P_g$","meaning":"air-gap power","unit":"$\\text{W}$"},{"symbol":"$P_{rcl}$","meaning":"rotor copper loss","unit":"$\\text{W}$"},{"symbol":"$P_m$","meaning":"developed mechanical power","unit":"$\\text{W}$"},{"symbol":"$s$","meaning":"slip, as a decimal","unit":null}]'::jsonb, 'Rotor efficiency is at most (1 − s): high-slip operation wastes power in the rotor.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'equivalent circuit' AND s."active"), NULL, true, 'PENDING', now(), now()
