SELECT gen_random_uuid()::text, 'formula', '$\theta = \frac{360°}{\text{steps/rev}}$', 'Stepper Motor Step Angle and Speed', '$\text{VR: } \theta = \frac{N_s - N_r}{N_sN_r}360°;\quad \text{hybrid: } \theta = \frac{360°}{2mN_r};\quad n = \frac{\theta f_p}{6}\ \text{rpm}$', NULL, 'How far a stepper turns per pulse, and its speed from the pulse rate.', '[{"symbol":"$N_s, N_r$","meaning":"stator and rotor teeth (variable reluctance)","unit":null},{"symbol":"$m$","meaning":"phases","unit":null},{"symbol":"$f_p$","meaning":"pulse rate, steps per second","unit":null},{"symbol":"$\\theta$","meaning":"step angle, degrees","unit":null}]'::jsonb, 'A two-phase hybrid with 50 rotor teeth: 1.8° per step, 200 steps per revolution.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'special machines (stepper, servo)' AND s."active"), NULL, true, 'PENDING', now(), now()
