SELECT gen_random_uuid()::text, 'formula', '$R_1 + R_2 = \frac{P_{br}}{3I_{br}^2}$', 'Induction Motor No-Load and Blocked-Rotor Tests', '$\text{blocked: } R_1 + R_2 = \frac{P_{br}}{3I_{br}^2},\ |Z| = \frac{V_{br}}{\sqrt3I_{br}};\quad \text{no load: } P_{nl} - 3I_{nl}^2R_1 = P_{core} + P_{f\&w}$', '$\Omega$', 'The equivalent circuit of an induction motor from two tests, like a transformer''s.', '[{"symbol":"$P_{br}, I_{br}, V_{br}$","meaning":"blocked-rotor power, line current, line voltage","unit":null},{"symbol":"$P_{nl}, I_{nl}$","meaning":"no-load power and current","unit":null}]'::jsonb, 'R₁ comes from a dc test; R₂ is what is left. X₁ and X₂ are usually split by motor class.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'machine testing and efficiency' AND s."active"), NULL, false, 'PENDING', now(), now()
