INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$X_d = \frac{V_{max}}{I_{min}}$', 'Slip Test for X_d and X_q', '$X_d = \frac{V_{\max}}{I_{\min}},\qquad X_q = \frac{V_{\min}}{I_{\max}}\quad (\text{per phase})$', '$\Omega$', 'Direct- and quadrature-axis reactances of a salient-pole machine from one slow-slip test.', '[{"symbol":"$V, I$","meaning":"armature voltage and current as the rotor slips slowly, field open","unit":null}]'::jsonb, 'X_d is the larger: the field poles line up with the d axis.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE' AND s."normKey" = 'machine testing and efficiency' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Machinery 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
